// `fabrica tests-map [<path>] [--force]` - generates a project's
// committed test map from its colocated foo.ts / foo.test.ts convention
// (Client ruling: "Generated by a Fabrica command from the project's
// conventions, committed, hand-editable afterwards").
//
// Two refusals, both loud, both for the same reason - a test map that
// quietly says less than the truth is worse than none at all, because
// every brief and every delivery then reports from it as if it were
// complete:
//
//   - an existing file is never overwritten without --force, since the
//     whole point is that a human edits it afterwards;
//   - a project where the convention finds nothing writes nothing,
//     rather than committing an empty map that would report every
//     touched file as unmapped forever.
//
// Denied to the chat agent in every shipped skill/<harness>/settings.json
// (src/cli/skill-settings.test.ts's NEVER_FROM_CHAT_COMMANDS): it writes
// a file into the Client's own checkout, which is exactly the
// off-the-books edit those templates exist to prevent.

import { existsSync, statSync } from "node:fs";
import { relative, resolve } from "node:path";

import { generatedHeader, generateTestMap, TEST_MAP_FILENAME, testMapPath, writeTestMap } from "../index.ts";
import { CliError } from "./errors.ts";
import { parseTestsMapArgs, TESTS_MAP_USAGE } from "./tests-map-args.ts";

export const TESTS_MAP_HELP = `Usage: ${TESTS_MAP_USAGE}

Writes <path>/${TEST_MAP_FILENAME}: which tests cover which files, one
entry per line - a glob pattern, a colon, then comma-separated test
files or commands. <path> defaults to the current directory.

Generated from the project's colocated foo.ts / foo.test.ts convention:
each test file is mapped to itself, and to its colocated source where
there is one. A source file with no colocated test of its own is
deliberately left out - add a mapping by hand when you know what covers
it. Editing the file afterwards is expected; re-running this command
needs --force and discards those edits.

Once it is committed, every task's brief names the tests that task's
touched files map to and tells the worker to run exactly those first and
the whole suite afterwards. Each delivery then records which of them the
worker says it ran, which touched files the map covers with nothing, and
any mapping naming a test file the project no longer has.

Denied to the chat agent - only you can run it, because it writes into
your own checkout.
`;

export function runTestsMapCommand(
  argv: string[],
  io: { stdout: (line: string) => void; stderr: (line: string) => void },
  cwd: string = process.cwd()
): number {
  let args;
  try {
    args = parseTestsMapArgs(argv);
  } catch (err) {
    io.stderr(err instanceof CliError ? err.message : String(err));
    return 1;
  }

  const project = resolve(cwd, args.pathArg);
  if (!existsSync(project) || !statSync(project).isDirectory()) {
    io.stderr(
      `fabrica tests-map: "${args.pathArg}" is not a directory (looked for ${project}). Pass the path to the ` +
        `project you want a test map for, or run this from inside it.`
    );
    return 1;
  }

  const path = testMapPath(project);
  if (existsSync(path) && !args.force) {
    io.stderr(
      `fabrica tests-map: ${path} already exists, and this command would replace it wholesale - including ` +
        `every mapping added to it by hand, which is what it is for. Re-run with --force if that is what you ` +
        `want, or edit the file directly.`
    );
    return 1;
  }

  const entries = generateTestMap(project);
  if (entries.length === 0) {
    io.stderr(
      `fabrica tests-map: found no test files under ${project}, so there is no mapping to generate and ` +
        `nothing was written. This command reads the colocated convention - a test named "foo.test.ts" (or ` +
        `"foo.spec.ts") beside the "foo.ts" it covers. Write ${TEST_MAP_FILENAME} by hand if this project ` +
        `names its tests some other way: one line per entry, a glob pattern, a colon, then comma-separated ` +
        `test files or commands.`
    );
    return 1;
  }

  writeTestMap(project, entries, generatedHeader());

  const tests = new Set(entries.flatMap((entry) => entry.tests));
  io.stdout(
    `wrote ${relative(cwd, path) || path}: ${entries.length} ${entries.length === 1 ? "entry" : "entries"} ` +
      `naming ${tests.size} ${tests.size === 1 ? "test" : "tests"}.`
  );
  io.stdout(
    `Commit it, then edit it by hand where the convention missed something - a source file with no colocated ` +
      `test of its own has no mapping, and a task touching one is reported as unmapped on its delivery.`
  );
  return 0;
}
